"""Lexicographic periodic shortest lineages and independent artifact auditing."""
import heapq
from exactcal import calibrate, valid_calibration, valid_cycle
from exactfabric import Calendar


def envelope(cal, guard, witnesses=False):
    cal.build_graph()
    size, n, radix = cal.size, cal.n, cal.radix
    labels = [None] * size
    pred = [None] * size if witnesses else None
    heap = [(0, v) for v in cal.sources]
    heapq.heapify(heap)
    for v in cal.sources:
        labels[v] = 0
    pop, push = heapq.heappop, heapq.heappush
    adj, waiting = cal.adj, cal.wait_encoded
    while heap:
        dist, v = pop(heap)
        if labels[v] != dist:
            continue
        dest = v + n
        if dest >= size:
            dest -= size
        candidate = dist + waiting[v]
        old = labels[dest]
        if old is None or candidate < old:
            labels[dest] = candidate
            if witnesses:
                pred[dest] = [v, -1]
            push(heap, (candidate, dest))
        edges = adj[v]
        if edges is not None:
            for dest, weight, code, margin in edges:
                if guard > margin:
                    continue
                candidate = dist + weight
                old = labels[dest]
                if old is None or candidate < old:
                    labels[dest] = candidate
                    if witnesses:
                        pred[dest] = [v, code]
                    push(heap, (candidate, dest))
    peak = 0
    for v, label in enumerate(labels):
        if label is None:
            return None, labels, pred
        peak = max(peak, label // radix + cal.wait[v])
    return peak, labels, pred


def objectives(cal, witnesses=False):
    cal.build_graph()
    peaks = []
    guard = None
    selected_labels = None
    selected_pred = None
    settings = cal.fabric['guards_ns']
    for idx, setting in enumerate(settings):
        # Guard changes matter only when an eligible edge actually disappears.
        # In particular, distinct timer settings can have identical envelopes.
        if idx in cal.graph_changes:
            peak, labels, pred = envelope(cal, setting, witnesses and guard is None)
        peaks.append(peak)
        if peak is None:
            # Increasing the guard can only delete edges, never restore a clock
            # lineage. All remaining peaks must therefore be unknown as well.
            peaks.extend([None] * (len(settings) - idx - 1))
            break
        if guard is None and setting * 1000000000 >= peak + cal.fabric['reconfig_ns'] * 1000000000:
            guard = setting
            selected_labels = labels
            selected_pred = pred
    return peaks, guard, selected_labels, selected_pred


def warmup(cal, labels):
    # A minimal-bound lineage of minimum age A is available at tick k*P+p
    # exactly when k*P+p >= A: its anchor then starts at a nonnegative tick.
    k = 0
    for v, label in enumerate(labels):
        age = label % cal.radix
        phase = v // cal.n
        k = max(k, (age - phase + cal.p - 1) // cal.p)
    return k


def compile_plan(profile, fabric):
    calibration = calibrate(profile)
    if calibration['status'] == 'inconsistent':
        return calibration
    cal = Calendar(profile, fabric, calibration)
    peaks, guard, labels, pred = objectives(cal, True)
    result = {'status': 'ok', 'profile': calibration, 'period_rounds': cal.p,
              'peaks_as': peaks, 'guard_ns': guard, 'bounds_as': None,
              'age_rounds': None, 'pred': None, 'warmup_cycle': None}
    if guard is not None:
        bounds = [label // cal.radix for label in labels]
        ages = [label % cal.radix for label in labels]
        result['bounds_as'] = [bounds[i:i + cal.n] for i in range(0, cal.size, cal.n)]
        result['age_rounds'] = [ages[i:i + cal.n] for i in range(0, cal.size, cal.n)]
        result['pred'] = [pred[i:i + cal.n] for i in range(0, cal.size, cal.n)]
        result['warmup_cycle'] = warmup(cal, labels)
    return result


def same_integer(a, b):
    return type(a) is int and a == b


def same_nullable_integer(a, b):
    return a is None if b is None else same_integer(a, b)


def check_plan(profile, fabric, proposal):
    # Inconsistency is a self-contained proof, with no dependence on the
    # compiler's choice of negative cycle.
    if proposal['status'] == 'inconsistent':
        return valid_cycle(profile, proposal)
    calibration = calibrate(profile)
    if calibration['status'] != 'ok':
        return False
    if not valid_calibration(profile, proposal['profile'], calibration):
        return False
    cal = Calendar(profile, fabric, calibration)
    if not same_integer(proposal['period_rounds'], cal.p):
        return False
    peaks, guard, labels, _ = objectives(cal)
    if len(proposal['peaks_as']) != len(peaks) or any(not same_nullable_integer(a, b) for a, b in zip(proposal['peaks_as'], peaks)):
        return False
    if not same_nullable_integer(proposal['guard_ns'], guard):
        return False
    if guard is None:
        return all(proposal[key] is None for key in ('bounds_as', 'age_rounds', 'pred', 'warmup_cycle'))
    if not same_integer(proposal['warmup_cycle'], warmup(cal, labels)):
        return False
    matrices = [proposal[key] for key in ('bounds_as', 'age_rounds', 'pred')]
    if any(matrix is None or len(matrix) != cal.p or any(len(row) != cal.n for row in matrix) for matrix in matrices):
        return False
    bounds, ages, pred = ([cell for row in matrix for cell in row] for matrix in matrices)
    for v, label in enumerate(labels):
        if label is None:
            if bounds[v] is not None or ages[v] is not None or pred[v] is not None:
                return False
        elif not same_integer(bounds[v], label // cal.radix) or not same_integer(ages[v], label % cal.radix):
            return False
    # Labels are compared with independently computed optima, while witnesses
    # are checked as actual steps, never compared with a chosen shortest tree.
    for v, label in enumerate(labels):
        if label is None or cal.anchors[v]:
            if pred[v] is not None:
                return False
            continue
        step = pred[v]
        if not isinstance(step, list) or len(step) != 2:
            return False
        prev, kind = step
        if type(prev) is not int or not 0 <= prev < cal.size or type(kind) is not int:
            return False
        if labels[prev] is None:
            return False
        phase, src_node = divmod(prev, cal.n)
        dest_phase, dest_node = divmod(v, cal.n)
        if kind == -1:
            if dest_node != src_node or dest_phase != (phase + 1) % cal.p:
                return False
            weight = cal.wait_encoded[prev]
        else:
            if not 0 <= kind < len(cal.directions):
                return False
            src, dst, _, _, _, rounds, hop, _, _, _ = cal.directions[kind]
            if src != src_node or dst != dest_node or dest_phase != (phase + rounds) % cal.p:
                return False
            if not cal.eligible(phase, kind, guard):
                return False
            weight = (hop + cal.aging(phase, kind)) * cal.radix + rounds
        if label != labels[prev] + weight:
            return False
    return True


def audit(profile, fabric, proposal):
    # Union alternatives of a well-typed artifact may still be semantically
    # incompatible (for example a null matrix with a claimed finite guard).
    try:
        return {'valid': bool(check_plan(profile, fabric, proposal))}
    except (KeyError, TypeError, IndexError, ValueError):
        return {'valid': False}
"""Periodic sampled calendar. Time is in ns; error arithmetic is Python integers."""
from math import gcd
from bisect import bisect_right


class Calendar:
    def __init__(self, profile, fabric, calibration):
        self.fabric = f = fabric
        self.n = n = f['n']
        self.t = t = f['interval_ns']
        self.s = s = f['slice_ns']
        self.o = o = f['offset_ns']
        self.q = q = len(f['slices'])
        self.p = p = q * s // gcd(t, q * s)
        self.size = n * p
        # Every step has duration at most 16. Every lex-optimal path is simple,
        # since even a zero-error cycle has positive elapsed age. This radix
        # therefore encodes (error,age) exactly for all shortest paths.
        self.radix = 16 * self.size + 1
        self.slice_at = [(o + phase * t) // s % q for phase in range(p)]
        self.rho = [(o + phase * t) % s for phase in range(p)]
        self.slice_sets = [set(row) for row in f['slices']]

        changes = [[0] * (p + 1) for _ in range(n)]
        for i, start, end, extra in f['heat']:
            changes[i][start] += extra
            changes[i][end] -= extra
        self.rates = rates = []
        self.prefix = []
        for i in range(n):
            cur = f['drift_ppb'][i]
            row = []
            for phase in range(p):
                cur += changes[i][phase]
                row.append(cur)
            rates.append(row)
            prefix = [0]
            for phase in range(p + 16):
                prefix.append(prefix[-1] + row[phase % p])
            self.prefix.append(prefix)
        self.wait = [rates[i][phase] * t for phase in range(p) for i in range(n)]
        self.wait_encoded = [w * self.radix + 1 for w in self.wait]

        self.anchors = bytearray(self.size)
        self.anchor_nodes = [set() for _ in range(p)]
        for i, start, end in f['anchors']:
            for phase in range(start, end):
                self.anchors[phase * n + i] = 1
                self.anchor_nodes[phase].add(i)
        self.sources = [v for v, yes in enumerate(self.anchors) if yes]

        black = [0] * len(f['links'])
        for link, start, end in f['blackouts']:
            black[link] |= ((1 << (end - start)) - 1) << start
        # Duplicate the periodic bitmap far enough for every physical flight.
        self.black = []
        for mask in black:
            ext = mask
            for shift in range(p, p + 8, p):
                ext |= mask << shift
            self.black.append(ext)

        # tuple: source,destination,TX slot,flight ns,ceil flight,step rounds,
        # calibrated hop bound, correction,source group,destination group
        self.directions = []
        upper = calibration['upper_ps']
        jit = profile['jitter_ps']
        for link in f['links']:
            for direction in range(2):
                src, slot, a = link['ends'][direction]
                dst, _, b = link['ends'][1 - direction]
                delay = link['delay_ns'][direction]
                flight = (delay + t - 1) // t
                rounds = flight + link['defer_rounds'][direction]
                hop = (upper[a][b] + upper[b][a]) * 500000 + (jit[a] + jit[b]) * 1000000
                correction = (upper[a][b] - upper[b][a]) * 500000
                self.directions.append((src, dst, slot, delay, flight, rounds,
                                        hop, correction, a, b))
        self.adj = None

    def blocked(self, phase, code):
        flight = self.directions[code][4]
        return bool((self.black[code // 2] >> phase) & ((1 << flight) - 1))

    def margin(self, phase, code):
        return min(self.rho[phase], self.s - self.rho[phase] - self.directions[code][3])

    def eligible(self, phase, code, guard):
        return (code // 2 in self.slice_sets[self.slice_at[phase]]
                and not self.blocked(phase, code)
                and self.margin(phase, code) >= guard)

    def aging(self, phase, code):
        _, dst, _, delay, flight, rounds, _, _, _, _ = self.directions[code]
        pr = self.prefix[dst]
        # A non-boundary arrival leaves one partial interval, followed by the
        # processing defer intervals. An exact-boundary arrival has no partial.
        return ((pr[phase + rounds] - pr[phase + flight]) * self.t
                + (flight * self.t - delay) * self.rates[dst][(phase + flight - 1) % self.p])

    def build_graph(self):
        if self.adj is not None:
            return
        n, p, radix = self.n, self.p, self.radix
        adj = [None] * self.size
        guards = self.fabric['guards_ns']
        smallest_guard = guards[0]
        self.graph_changes = {0}
        for phase in range(p):
            off = phase * n
            for lid in self.fabric['slices'][self.slice_at[phase]]:
                for code in (2 * lid, 2 * lid + 1):
                    margin = self.margin(phase, code)
                    if margin < smallest_guard or self.blocked(phase, code):
                        continue
                    # At this hardware setting the edge first disappears.
                    self.graph_changes.add(bisect_right(guards, margin))
                    src, dst, _, _, _, rounds, hop, _, _, _ = self.directions[code]
                    v = off + src
                    to = (phase + rounds) % p * n + dst
                    weight = (hop + self.aging(phase, code)) * radix + rounds
                    if adj[v] is None:
                        adj[v] = []
                    adj[v].append((to, weight, code, margin))
        self.adj = adj
